export interface VoiceParseResult {
  normalizedTranscript: string;
  success: boolean;
  action: VoiceCommandAction;
}

export const SUPPORTED_COMMAND_PATTERNS = [
  "thêm khối bắt đầu",
  "thêm khối in",
  "thêm khối lặp 3 lần",
  "thêm khối điều kiện",
  "thêm biến",
